// The core's mip chains (ABI 35): mip_chain.h has the contract.
#include "mip_chain.h"

#include "core_shaders.h" // generated by CMake: shaders/mip_box.comp and shaders/mip_box_rgba8.comp

#include <rhi/qshader.h>

namespace srpss_core {

int mipChainLevels(const QSize &size)
{
    int levels = 1;
    for (QSize s = size; s.width() > 1 || s.height() > 1; ++levels)
        s = QSize(qMax(1, s.width() / 2), qMax(1, s.height() / 2));
    return qMin(levels, kMaxChainLevels);
}

void MipChain::release()
{
    for (int level = kMaxChainLevels - 1; level >= 0; --level)
        this->level[level].reset();
    levels = 0;
    bindings = 0;
    size = QSize();
}

MipChainKernel::~MipChainKernel()
{
    release();
}

bool MipChainKernel::supports(QRhiTexture::Format format)
{
    return format == QRhiTexture::RGBA8 || format == QRhiTexture::RGBA16F;
}

MipChainKernel::Kernel *MipChainKernel::kernel(QRhiTexture::Format format)
{
    return format == QRhiTexture::RGBA16F ? &m_rgba16f : format == QRhiTexture::RGBA8 ? &m_rgba8 : nullptr;
}

const MipChainKernel::Kernel *MipChainKernel::kernel(QRhiTexture::Format format) const
{
    return format == QRhiTexture::RGBA16F ? &m_rgba16f : format == QRhiTexture::RGBA8 ? &m_rgba8 : nullptr;
}

bool MipChainKernel::ensure(QRhi *rhi, QRhiTexture::Format format, QString *error)
{
    if (m_rhi != rhi)
        release();                            // another QRhi: its pipelines are not this one's
    Kernel *k = kernel(format);
    if (!k) {
        *error = QStringLiteral("the core's box kernel makes the levels of RGBA8 and RGBA16F textures only");
        return false;
    }
    if (k->pipeline)
        return true;
    const bool half = format == QRhiTexture::RGBA16F;
    const QShader shader = half
        ? QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(mip_box_comp_qsb), int(mip_box_comp_qsb_size)))
        : QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(mip_box_rgba8_comp_qsb),
                                             int(mip_box_rgba8_comp_qsb_size)));
    if (!shader.isValid() || !rhi->isFeatureSupported(QRhi::Compute)) {
        *error = QStringLiteral("a mip chain needs QRhi::Compute and the core's box kernel (shaders/%1)")
                     .arg(half ? QStringLiteral("mip_box.comp") : QStringLiteral("mip_box_rgba8.comp"));
        return false;
    }
    const QRhiShaderResourceBinding::StageFlags cs = QRhiShaderResourceBinding::ComputeStage;
    // The layout's own texture (two levels): the pipeline never depends on a texture's objects.
    k->layoutTexture.reset(rhi->newTexture(format, QSize(2, 2), 1,
                                           QRhiTexture::MipMapped | QRhiTexture::UsedWithLoadStore));
    k->layoutTexture->setName(QByteArrayLiteral("srpss core mip chain layout"));
    bool ok = k->layoutTexture->create();
    k->layout.reset(rhi->newShaderResourceBindings());
    k->layout->setName(QByteArrayLiteral("srpss core mip chain layout"));
    k->layout->setBindings({ QRhiShaderResourceBinding::imageLoad(0, cs, k->layoutTexture.get(), 0),
                             QRhiShaderResourceBinding::imageStore(1, cs, k->layoutTexture.get(), 1) });
    ok = ok && k->layout->create();
    k->pipeline.reset(rhi->newComputePipeline());
    k->pipeline->setName(QByteArrayLiteral("srpss core mip chain"));
    k->pipeline->setShaderStage({ QRhiShaderStage::Compute, shader });
    k->pipeline->setShaderResourceBindings(k->layout.get());
    ok = ok && k->pipeline->create();
    if (!ok) {
        k->pipeline.reset();
        k->layout.reset();
        k->layoutTexture.reset();
        *error = QStringLiteral("the core's box kernel could not be created");
        return false;
    }
    m_rhi = rhi;
    return true;
}

bool MipChainKernel::bind(QRhi *rhi, QRhiTexture *texture, const QSize &size, MipChain *chain, QString *error)
{
    chain->release();
    if (!rhi || !texture || size.isEmpty()) {
        *error = QStringLiteral("a mip chain needs a texture");
        return false;
    }
    if (!(texture->flags() & QRhiTexture::MipMapped) || !(texture->flags() & QRhiTexture::UsedWithLoadStore)) {
        *error = QStringLiteral("a mip chain's texture is MipMapped and UsedWithLoadStore");
        return false;
    }
    if (!ensure(rhi, texture->format(), error))
        return false;
    const QRhiShaderResourceBinding::StageFlags cs = QRhiShaderResourceBinding::ComputeStage;
    const int levels = mipChainLevels(size);
    for (int level = 1; level < levels; ++level) {
        RhiOwned<QRhiShaderResourceBindings> &srb = chain->level[level];
        srb.reset(rhi->newShaderResourceBindings());
        srb->setName(QByteArrayLiteral("srpss core mip chain ") + texture->name());
        srb->setBindings({ QRhiShaderResourceBinding::imageLoad(0, cs, texture, level - 1),
                           QRhiShaderResourceBinding::imageStore(1, cs, texture, level) });
        ++chain->bindings;
        if (!srb->create()) {
            chain->release();
            *error = QStringLiteral("%1: its mip chain's bindings could not be created")
                         .arg(QString::fromLatin1(texture->name()));
            return false;
        }
    }
    chain->levels = levels;
    chain->format = texture->format();
    chain->size = size;
    return true;
}

void MipChainKernel::record(QRhiCommandBuffer *cb, const MipChain &chain) const
{
    const Kernel *k = kernel(chain.format);
    if (!cb || !k || !k->pipeline)
        return;
    for (int level = 1; level < chain.levels; ++level) {
        const int width = qMax(1, chain.size.width() >> level);
        const int height = qMax(1, chain.size.height() >> level);
        cb->beginComputePass();
        cb->setComputePipeline(k->pipeline.get());
        cb->setShaderResources(chain.level[level].get());
        cb->dispatch((width + 7) / 8, (height + 7) / 8, 1);
        cb->endComputePass();
    }
}

void MipChainKernel::release()
{
    for (Kernel *k : { &m_rgba16f, &m_rgba8 }) {
        k->pipeline.reset();
        k->layout.reset();
        k->layoutTexture.reset();
    }
    m_rhi = nullptr;
}

} // namespace srpss_core
